export function icon(name, size = 22) {
  return `<svg class="icon icon-${name in paths ? name : 'info'}" width="${Number(size) || 22}" height="${Number(size) || 22}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name] || paths.info}</svg>`;
}
